/**
 * Structural HTML Export
 *
 * Produces a portable offline HTML snapshot of the structural map.
 *
 * Architecture note (PRD §9):
 *   The full Archify CLI pipeline (validate → deliver → visual-check) runs
 *   server-side as a bounded subprocess.  This client-side module provides:
 *     1. A lightweight fallback export when the server-side Archify
 *        renderer is not yet configured (structural HTML only).
 *     2. The data preparation that feeds the server-side compiler.
 *
 * The fallback export:
 *   - Uses only trusted templates with escaped data
 *   - Never executes repository code
 *   - Embeds manifest/provenance information
 *   - Clearly labels deferred capabilities
 *   - Works offline with no external requests
 *
 * INTEGRATION_SLOT: proposals.detail
 * When the Archify server-side renderer is connected, replace
 * triggerFallbackExport() with a call to the export endpoint and
 * download the validated artifact.
 */

import type { FilePage, Graph, Snapshot } from '../../types/v1'

export interface ExportManifest {
  schema_version: '1.0'
  export_type: 'structural_map'
  snapshot_id: string
  project_id: string
  source_kind: string
  source_ref?: string
  exported_at: string
  entity_count: number
  relation_count: number
  file_count: number
  compiler_version: string
  deferred_capabilities: string[]
}

/**
 * Build the export manifest for provenance.
 * This is passed to the Archify compiler and embedded in the export.
 */
export function buildExportManifest(
  snapshot: Snapshot,
  graph: Graph,
  filePage: FilePage,
): ExportManifest {
  return {
    schema_version: '1.0',
    export_type: 'structural_map',
    snapshot_id: snapshot.id,
    project_id: snapshot.project_id,
    source_kind: snapshot.source.kind,
    source_ref: snapshot.source.resolved_commit ?? snapshot.source.archive_digest,
    exported_at: new Date().toISOString(),
    entity_count: graph.entities.length,
    relation_count: graph.relations.length,
    file_count: filePage.total,
    compiler_version: '1.0.0-structural-fallback',
    deferred_capabilities: [
      'summaries.context-panel: AI file/folder summaries (not connected)',
      'dependencies.workspace: Import/dependency edges (not connected)',
      'reuse.findings: Reusable function discovery (not connected)',
      'duplicates.compare: Duplicate detection (not connected)',
      'unused.review: Unused-code review (not connected)',
      'ask.workspace: Ask Grepo Q&A (not connected)',
      'proposals.detail: Change proposals (not connected)',
    ],
  }
}

/**
 * Escape a string for safe embedding in HTML.
 * Used for all repository-derived content in the export.
 */
function escHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

/**
 * Escape a string for safe embedding in a <script> JSON block.
 * Prevents repository text from escaping the JSON context.
 */
function escJson(obj: unknown): string {
  return JSON.stringify(obj)
    .replace(/<\/script>/gi, '<\\/script>')
    .replace(/<!--/g, '<\\!--')
}

/**
 * Generate the fallback structural HTML export.
 *
 * This is a fully self-contained static HTML file that:
 *   - Shows the structural map as an SVG
 *   - Includes provenance metadata
 *   - Explicitly labels deferred capabilities
 *   - Works offline
 *   - Does NOT include code excerpts by default (per excerpt policy)
 */
export function generateStructuralHtml(
  snapshot: Snapshot,
  graph: Graph,
  manifest: ExportManifest,
): string {
  const title = escHtml(
    snapshot.source.repo
      ? `${snapshot.source.owner ?? ''}/${snapshot.source.repo}`
      : `Snapshot ${snapshot.id.slice(0, 8)}`,
  )

  const revisionLabel = escHtml(
    snapshot.source.resolved_commit
      ? snapshot.source.resolved_commit.slice(0, 12)
      : snapshot.source.archive_digest?.slice(0, 12) ?? 'unknown',
  )

  // Build simple SVG representation
  const NODE_W = 140
  const NODE_H = 36
  const H_GAP = 20
  const V_GAP = 20
  const PADDING = 40

  const entityMap = new Map(graph.entities.map(e => [e.id, e]))
  const childrenMap = new Map<string, string[]>()
  for (const rel of graph.relations) {
    if (rel.kind === 'contains') {
      const list = childrenMap.get(rel.source_id) ?? []
      list.push(rel.target_id)
      childrenMap.set(rel.source_id, list)
    }
  }

  interface SvgNode {
    id: string
    label: string
    kind: string
    x: number
    y: number
    depth: number
    children: SvgNode[]
  }

  let xCounter = PADDING
  function buildSvgNode(entityId: string, depth: number): SvgNode {
    const entity = entityMap.get(entityId)
    const label = entity?.label ?? entityId.slice(0, 12)
    const kind = entity?.kind ?? 'file'
    const childIds = childrenMap.get(entityId) ?? []
    const children = childIds.map(id => buildSvgNode(id, depth + 1))
    const node: SvgNode = {
      id: entityId,
      label,
      kind,
      x: 0,
      y: PADDING + depth * (NODE_H + V_GAP),
      depth,
      children,
    }
    if (children.length === 0) {
      node.x = xCounter
      xCounter += NODE_W + H_GAP
    } else {
      const first = children[0]
      const last = children[children.length - 1]
      node.x = (first.x + last.x + NODE_W) / 2 - NODE_W / 2
    }
    return node
  }

  const roots = graph.entities.filter(e => !e.parent_id || e.kind === 'repository')
  const svgRoots = roots.map(r => buildSvgNode(r.id, 0))

  function flattenSvg(nodes: SvgNode[]): SvgNode[] {
    const result: SvgNode[] = []
    function visit(n: SvgNode) { result.push(n); n.children.forEach(visit) }
    nodes.forEach(visit)
    return result
  }

  const allSvgNodes = flattenSvg(svgRoots)
  const svgW = Math.max(600, xCounter + PADDING)
  const maxDepth = allSvgNodes.reduce((m, n) => Math.max(m, n.depth), 0)
  const svgH = PADDING * 2 + (maxDepth + 1) * (NODE_H + V_GAP)

  const nodeColors: Record<string, string> = {
    repository: '#C6F84A',
    directory: '#F3F5F0',
    file: '#FFFFFF',
    virtual_group: '#F2F85B',
  }

  const svgNodes = allSvgNodes.map(n => {
    const fill = nodeColors[n.kind] ?? '#FFFFFF'
    const stroke = n.kind === 'repository' ? '#a0d020' : '#DFE5DA'
    const label = n.label.length > 18 ? `${n.label.slice(0, 16)}…` : n.label
    return `<g class="map-node" transform="translate(${n.x},${n.y})">
      <rect width="${NODE_W}" height="${NODE_H}" rx="6" fill="${fill}" stroke="${stroke}" stroke-width="1"/>
      <text x="${NODE_W / 2}" y="${NODE_H / 2 + 4}" text-anchor="middle" font-size="11" font-family="system-ui,sans-serif" fill="#172019">${escHtml(label)}</text>
    </g>`
  }).join('\n    ')

  const svgEdges = graph.relations
    .filter(r => r.kind === 'contains')
    .map(r => {
      const src = allSvgNodes.find(n => n.id === r.source_id)
      const tgt = allSvgNodes.find(n => n.id === r.target_id)
      if (!src || !tgt) return ''
      return `<line x1="${src.x + NODE_W / 2}" y1="${src.y + NODE_H}" x2="${tgt.x + NODE_W / 2}" y2="${tgt.y}" stroke="#DFE5DA" stroke-width="1"/>`
    })
    .join('\n    ')

  const deferredList = manifest.deferred_capabilities
    .map(c => `<li>${escHtml(c)}</li>`)
    .join('\n          ')

  // Table of files (top 50 only to keep size reasonable)
  const fileList = graph.entities
    .filter(e => e.kind === 'file')
    .slice(0, 50)
    .map(e => `<tr><td style="font-family:monospace;font-size:11px">${escHtml(e.path ?? e.label)}</td><td style="font-size:11px">${escHtml(e.metadata?.language as string ?? '')}</td></tr>`)
    .join('\n')

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Grepo: ${title} — Structural Map</title>
<style>
body{margin:0;padding:0;font-family:system-ui,sans-serif;background:#FAFBF7;color:#172019;}
header{background:#FFFFFF;border-bottom:1px solid #DFE5DA;padding:16px 32px;display:flex;align-items:center;gap:16px;}
h1{margin:0;font-size:18px;font-weight:700;}
.badge{padding:3px 8px;background:#F3F5F0;border:1px solid #DFE5DA;border-radius:6px;font-family:monospace;font-size:10px;color:#526057;}
main{padding:32px;}
.card{background:#FFFFFF;border:1px solid #DFE5DA;border-radius:16px;padding:24px;margin-bottom:24px;box-shadow:0 4px 16px rgba(23,32,25,.04);}
h2{margin:0 0 16px;font-size:16px;font-weight:700;}
.svg-scroll{overflow:auto;border:1px solid #DFE5DA;border-radius:8px;background:#F9FAF7;}
.slot-notice{background:#F3F5F0;border:1px dashed #DFE5DA;border-radius:12px;padding:16px 20px;}
.slot-notice h3{margin:0 0 8px;font-size:14px;}
.slot-notice ul{margin:0;padding:0 0 0 18px;font-size:12px;color:#526057;}
table{width:100%;border-collapse:collapse;font-size:12px;}
th{text-align:left;padding:6px 10px;border-bottom:1px solid #DFE5DA;font-family:monospace;font-size:9px;text-transform:uppercase;color:#526057;}
td{padding:6px 10px;border-bottom:1px solid #DFE5DA;color:#526057;}
.provenance{font-family:monospace;font-size:11px;line-height:1.8;color:#526057;}
footer{text-align:center;padding:24px;color:#526057;font-size:11px;border-top:1px solid #DFE5DA;margin-top:32px;}
</style>
</head>
<body>
<header>
  <svg width="28" height="28" viewBox="0 0 28 28"><rect width="28" height="28" rx="6" fill="#172019"/><text x="14" y="19" text-anchor="middle" font-size="13" font-weight="700" font-family="monospace" fill="#C6F84A">G</text></svg>
  <h1>Grepo — ${title}</h1>
  <span class="badge">Structural Map</span>
  <span class="badge">Revision: ${revisionLabel}</span>
  <span class="badge">Exported: ${escHtml(manifest.exported_at.split('T')[0])}</span>
</header>

<main>
  <div class="card">
    <h2>Repository Structure</h2>
    <p style="font-size:13px;color:#526057;margin:0 0 16px">
      ${graph.entities.length} entities &middot; ${graph.relations.filter(r => r.kind === 'contains').length} containment edges
      &middot; ${manifest.file_count} files inventoried
    </p>
    <div class="svg-scroll">
      <svg width="${svgW}" height="${svgH}" aria-label="Repository structure diagram">
        ${svgEdges}
        ${svgNodes}
      </svg>
    </div>
    ${graph.coverage.limitations.length ? `<p style="margin:12px 0 0;font-size:11px;color:#526057">${escHtml(graph.coverage.limitations[0])}</p>` : ''}
  </div>

  <div class="card">
    <h2>File Inventory (${manifest.file_count} files${manifest.file_count > 50 ? ', showing 50' : ''})</h2>
    <div style="max-height:320px;overflow:auto">
    <table>
      <thead><tr><th>Path</th><th>Language</th></tr></thead>
      <tbody>${fileList}</tbody>
    </table>
    </div>
  </div>

  <div class="slot-notice card">
    <h2 style="color:#526057;font-size:13px">Deferred Capabilities (Integration Slots)</h2>
    <p style="margin:0 0 10px;font-size:12px;color:#526057">
      The following features are not yet connected. This export contains structural analysis only.
      New questions, live search and AI features are disabled in offline mode.
    </p>
    <ul>
      ${deferredList}
    </ul>
  </div>

  <div class="card">
    <h2>Export Provenance</h2>
    <pre class="provenance">${escHtml(JSON.stringify(manifest, null, 2))}</pre>
  </div>
</main>

<footer>
  <p>Grepo structural map export &middot; Read-only, offline snapshot &middot; Source files are unchanged</p>
  <p style="margin:4px 0 0">Map rendering adapted from the Archify architecture diagram framework (MIT, Cocoon AI). See INTEGRATION_GUIDE.md for the full Archify integration path.</p>
</footer>

<!-- Manifest JSON for machine consumption (safe-encoded) -->
<script type="application/json" id="grepo-manifest">
${escJson(manifest)}
</script>

</body>
</html>`
}

/**
 * Trigger a browser download of the structural HTML export.
 */
export function downloadStructuralExport(
  snapshot: Snapshot,
  graph: Graph,
  manifest: ExportManifest,
): void {
  const html = generateStructuralHtml(snapshot, graph, manifest)
  const blob = new Blob([html], { type: 'text/html;charset=utf-8' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  const name = snapshot.source.repo ?? `snapshot-${snapshot.id.slice(0, 8)}`
  a.href = url
  a.download = `grepo-${name.replace(/[^a-z0-9\-_.]/gi, '_')}-structure.html`
  document.body.appendChild(a)
  a.click()
  document.body.removeChild(a)
  URL.revokeObjectURL(url)
}
